'use strict';
(() => {
const products = window.PET_PRODUCTS || [];
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const money = n => n.toLocaleString('ru-RU') + ' ₽';
const KEY = 'lapki-cart-v1';
const find = id => products.find(p => p.id === Number(id));
const safeQty = n => Math.max(1, Math.min(10, Math.trunc(Number(n)) || 1));
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const bagIcon = '<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M2 3h3l3 12h11l3-9H6M9 20h.01M18 20h.01"/></svg>';
const crossIcon = '<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m6 6 12 12M6 18 18 6"/></svg>';
let state = {items:[],coupon:'',delivery:'pickup'};
try {
 const saved = JSON.parse(localStorage.getItem(KEY));
 if (saved && Array.isArray(saved.items)) {
  const dedup = new Map();
  saved.items.slice(0,100).forEach(x => {if(find(x.id)){const kit=x.kit==='care'&&find(x.id).category==='accessories'?'care':'base';const key=Number(x.id)+'-'+kit;dedup.set(key,{id:Number(x.id),qty:safeQty(x.qty),kit});}});
  state={items:[...dedup.values()],coupon:saved.coupon==='LAPKI10'?'LAPKI10':'',delivery:saved.delivery==='courier'?'courier':'pickup'};
 }
} catch { /* Работаем в памяти, если хранилище недоступно. */ }
const itemKey = x => x.id+'-'+x.kit;
const unit = x => find(x.id).price+(x.kit==='care'?190:0);
const totals = () => {const subtotal=state.items.reduce((n,x)=>n+unit(x)*x.qty,0),discount=state.coupon==='LAPKI10'?Math.round(subtotal*.1):0,delivery=state.items.length&&state.delivery==='courier'?490:0;return {subtotal,discount,delivery,grand:subtotal-discount+delivery};};
const save = () => {try{localStorage.setItem(KEY,JSON.stringify(state));}catch{} refresh();};
let toastTimer;
function toast(text){const box=$('#toast');if(!box)return;box.textContent=text;box.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('visible'),3500);}
function add(id,qty=1,kit='base'){const p=find(id);if(!p)return;kit=p.category==='accessories'&&kit==='care'?'care':'base';const old=state.items.find(x=>x.id===p.id&&x.kit===kit);if(old){old.qty=Math.min(10,old.qty+safeQty(qty));}else{state.items.push({id:p.id,qty:safeQty(qty),kit});}save();toast(p.name+' — добавлено в корзину');}
function card(p){return `<article class="product-card" data-product="${p.id}"><a class="product-image" href="single.html?id=${p.id}"><img src="assets/${p.image}" width="600" height="600" loading="lazy" alt="${esc(p.name)}">${p.tag?`<span class="badge">${p.tag}</span>`:''}</a><div class="product-info"><p class="product-type">${({food:'Корма',care:'Уход и гигиена',toys:'Игрушки',accessories:'Аксессуары'}[p.category])}</p><h3><a href="single.html?id=${p.id}">${p.name}</a></h3><div class="product-bottom"><p class="price">${money(p.price)} <del>${money(p.oldPrice)}</del></p><button class="add-small" type="button" data-add="${p.id}" aria-label="Добавить ${esc(p.name)} в корзину">${bagIcon}</button></div></div></article>`;}
function renderCart(){const box=$('#cart-content');if(!box)return;if(!state.items.length){box.innerHTML=`<div class="empty-state">${bagIcon}<h2>Здесь будет ваш следующий комплект</h2><p>Добавьте товары из каталога или заполните корзину примером.</p><a class="button" href="catalog.html">Перейти в каталог →</a><button class="text-button" type="button" data-demo-cart>Заполнить примером</button></div>`;return;}box.innerHTML=`<div class="cart-table-wrap"><table class="cart-table"><caption>Выбранные товары. Количество можно изменить от 1 до 10.</caption><thead><tr><th scope="col">Товар</th><th scope="col">Цена</th><th scope="col">Количество</th><th scope="col">Сумма</th><th scope="col"><span class="sr-only">Действия</span></th></tr></thead><tbody>${state.items.map(x=>{const p=find(x.id),key=itemKey(x);return `<tr><td><div class="cart-product"><a href="single.html?id=${p.id}"><img src="assets/${p.image}" width="95" height="110" alt="${esc(p.name)}"></a><div><h3><a href="single.html?id=${p.id}">${p.name}</a></h3><p>${x.kit==='care'?'В подарочной упаковке':'Стандартная комплектация'}</p></div></div></td><td>${money(unit(x))}</td><td><label class="sr-only" for="qty-${key}">Количество ${p.name}</label><input class="cart-quantity" id="qty-${key}" type="number" min="1" max="10" value="${x.qty}" required data-qty="${key}"></td><td>${money(unit(x)*x.qty)}</td><td><button type="button" class="remove-item" data-remove="${key}" aria-label="Удалить ${esc(p.name)}">${crossIcon}</button></td></tr>`;}).join('')}</tbody></table></div><div class="cart-actions"><button class="outline-button" type="button" data-clear-cart>Очистить корзину</button><a class="outline-button" href="catalog.html">Продолжить покупки →</a></div>`;}
function renderCheckout(){const box=$('#checkout-items');if(!box)return;box.innerHTML=state.items.length?state.items.map(x=>{const p=find(x.id);return `<article class="summary-item"><a href="single.html?id=${p.id}"><img src="assets/${p.image}" width="60" height="70" alt="${esc(p.name)}"></a><div><h3>${p.name}</h3><p>${x.qty} шт. · ${x.kit==='care'?'в подарочной упаковке':'стандарт'}</p><span>${money(unit(x)*x.qty)}</span></div></article>`;}).join(''):'<p>В корзине пока нет товаров.</p><a class="text-button" href="catalog.html">Перейти в каталог →</a>';
 const submit=$('#place-order');if(submit)submit.disabled=!state.items.length;
}
function refresh(){const count=state.items.reduce((n,x)=>n+x.qty,0);$$('[data-cart-count]').forEach(el=>{el.textContent=count;el.closest('a').setAttribute('aria-label','Корзина: '+count+' товаров');});renderCart();renderCheckout();const t=totals();for(const key of ['subtotal','discount','delivery','grand'])$$('[data-'+key+']').forEach(el=>el.textContent=money(t[key]));const delivery=$('#cart-delivery');if(delivery)delivery.value=state.delivery;const coupon=$('#coupon');if(coupon&&!coupon.value)coupon.value=state.coupon;const checkout=$('#checkout-form');if(checkout){const radio=checkout.querySelector(`[name="delivery"][value="${state.delivery}"]`);if(radio)radio.checked=true;updateAddress();}}
document.addEventListener('click',e=>{const addButton=e.target.closest('[data-add]');if(addButton)add(addButton.dataset.add);const remove=e.target.closest('[data-remove]');if(remove){state.items=state.items.filter(x=>itemKey(x)!==remove.dataset.remove);save();toast('Товар удалён');}if(e.target.closest('[data-clear-cart]')){state.items=[];state.coupon='';save();toast('Корзина очищена');}if(e.target.closest('[data-demo-cart]')){state.items=[{id:123,qty:1,kit:'base'},{id:100,qty:1,kit:'base'},{id:104,qty:1,kit:'base'}];state.coupon='';save();toast('Добавлен демонстрационный комплект');}});
document.addEventListener('input',e=>{if(!e.target.matches('[data-qty]')||!e.target.validity.valid)return;const item=state.items.find(x=>itemKey(x)===e.target.dataset.qty);if(!item)return;item.qty=safeQty(e.target.value);try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}const row=e.target.closest('tr');if(row)row.children[3].textContent=money(unit(item)*item.qty);const t=totals();for(const key of ['subtotal','discount','delivery','grand'])document.querySelectorAll('[data-'+key+']').forEach(el=>el.textContent=money(t[key]));const count=state.items.reduce((n,x)=>n+x.qty,0);document.querySelectorAll('[data-cart-count]').forEach(el=>{el.textContent=count;el.closest('a').setAttribute('aria-label','Корзина: '+count+' товаров');});});
document.addEventListener('change',e=>{if(e.target.matches('[data-qty]')){const item=state.items.find(x=>itemKey(x)===e.target.dataset.qty);if(item){item.qty=safeQty(e.target.value);save();}}});
$('#cart-delivery')?.addEventListener('change',e=>{state.delivery=e.target.value==='courier'?'courier':'pickup';save();});
$('#coupon-form')?.addEventListener('submit',e=>{e.preventDefault();const code=$('#coupon').value.trim().toUpperCase();state.coupon=code==='LAPKI10'?code:'';save();$('#coupon-result').textContent=code==='LAPKI10'?'Промокод применён: скидка 10%.':code?'Этот код не найден. Попробуйте LAPKI10.':'Промокод удалён.';});
// Поиск, фильтрация, сортировка и постраничный каталог.
if($('#filters')){const form=$('#filters'),params=new URLSearchParams(location.search);let query=(params.get('q')||'').trim().slice(0,80),currentPage=1;const category=params.get('category');if(['food','care','toys','accessories'].includes(category))form.querySelector(`[name="category"][value="${category}"]`).checked=true;$('#search').value=query;if(query){$('#search-summary').hidden=false;$('#search-summary').textContent='Поиск: «'+query+'»';}
 function render(){const category=form.elements.category.value,brand=form.elements.brand.value,max=Number(form.elements.maxPrice.value),sort=$('#sort').value;let list=products.filter(p=>(category==='all'||p.category===category)&&(brand==='all'||p.brand===brand)&&p.price<=max&&(!query||(p.name+' '+p.brand).toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru'))));if(sort==='price-up')list.sort((a,b)=>a.price-b.price);if(sort==='price-down')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ru'));const pages=Math.max(1,Math.ceil(list.length/9));currentPage=Math.min(currentPage,pages);$('#result-count').textContent='Найдено товаров: '+list.length;$('#price-value').value=money(max);$('#catalog-grid').innerHTML=list.length?list.slice((currentPage-1)*9,currentPage*9).map(card).join(''):'<div class="empty-state"><h2>Ничего не найдено</h2><p>Попробуйте изменить фильтры или поисковый запрос.</p><a class="text-button" href="catalog.html">Показать весь каталог</a></div>';$('#pagination').innerHTML=Array.from({length:pages},(_,i)=>`<button type="button" data-page-number="${i+1}" aria-label="Страница ${i+1}"${i+1===currentPage?' aria-current="page"':''}>${i+1}</button>`).join('');}
 form.addEventListener('input',()=>{currentPage=1;render();});form.addEventListener('change',()=>{currentPage=1;render();});form.addEventListener('reset',()=>{query='';$('#search-summary').hidden=true;$('#search').value='';currentPage=1;setTimeout(render,0);});$('#sort').addEventListener('change',()=>{currentPage=1;render();});$('#pagination').addEventListener('click',e=>{if(e.target.dataset.pageNumber){currentPage=Number(e.target.dataset.pageNumber);render();$('#result-count').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});render();}
// Карточка выбранного товара.
if($('#product-form')){const params=new URLSearchParams(location.search),p=find(params.get('id'))||products[0];let imageIndex=0;const views=[p.image,...(p.altImage?[p.altImage]:[])];$('#detail-name').textContent=p.name;$('#detail-category').textContent=(({food:'КОРМА',care:'УХОД',toys:'ИГРУШКИ',accessories:'АКСЕССУАРЫ'}[p.category]))+' / '+p.brand.toUpperCase();$('#detail-description').textContent=p.description;$('#detail-price').textContent=money(p.price);document.title=p.name+' — карточка товара | ЛАПКИ';const meta=$('meta[name="description"]');if(meta)meta.content=p.name+' в учебном магазине ЛАПКИ: фотографии, комплектация и добавление в корзину.';if(p.category==='accessories'&&!$('#kit').querySelector('[value="care"]'))$('#kit').append(new Option('Подарочная упаковка · 190 ₽','care'));if(p.category!=='accessories')$('#kit').querySelector('[value="care"]')?.remove();function showImage(){const im=$('#detail-image');im.src='assets/'+views[imageIndex];im.alt=p.name+(imageIndex?' — другой ракурс':' — основной вид');$('#image-position').textContent=String(imageIndex+1).padStart(2,'0')+' / '+String(views.length).padStart(2,'0');$('#image-prev').disabled=views.length<2;$('#image-next').disabled=views.length<2;}$('#image-prev').addEventListener('click',()=>{imageIndex=(imageIndex+views.length-1)%views.length;showImage();});$('#image-next').addEventListener('click',()=>{imageIndex=(imageIndex+1)%views.length;showImage();});$('#kit').addEventListener('change',()=>$('#detail-price').textContent=money(p.price+($('#kit').value==='care'?190:0)));$('#product-form').addEventListener('submit',e=>{e.preventDefault();if(e.target.reportValidity())add(p.id,$('#quantity').value,$('#kit').value);});showImage();}
function updateAddress(){const form=$('#checkout-form');if(!form)return;const courier=state.delivery==='courier';$('#address-fields').hidden=!courier;$('#pickup-note').hidden=courier;['city','street'].forEach(name=>{const input=form.elements[name];input.disabled=!courier;input.required=courier;});}
const checkout=$('#checkout-form');let receipt='';
if(checkout){checkout.addEventListener('change',e=>{if(e.target.name==='delivery'){state.delivery=e.target.value;save();}});checkout.addEventListener('invalid',e=>{const details=e.target.closest('details');if(details)details.open=true;},true);const checkField=input=>{input.setCustomValidity('');if(['firstName','lastName','city','street'].includes(input.name)&&input.required&&input.value.trim().length<(Number(input.minLength)||2))input.setCustomValidity('Введите значение, не состоящее из пробелов.');if(input.name==='phone'){const digits=input.value.replace(/\D/g,'');if(digits.length<10||digits.length>15)input.setCustomValidity('Укажите телефон, содержащий от 10 до 15 цифр.');}};checkout.addEventListener('input',e=>{if(e.target instanceof HTMLInputElement)checkField(e.target);});checkout.addEventListener('submit',e=>{e.preventDefault();[...checkout.elements].filter(x=>x instanceof HTMLInputElement&&!x.disabled).forEach(checkField);if(!checkout.reportValidity())return;if(!state.items.length){$('#order-result').textContent='Сначала добавьте товары в корзину.';return;}const t=totals();receipt='ЛАПКИ — УЧЕБНЫЙ ЗАКАЗ\n\n'+state.items.map(x=>find(x.id).name+' · '+x.qty+' шт. · '+(x.kit==='care'?'в подарочной упаковке':'стандарт')+' · '+money(unit(x)*x.qty)).join('\n')+'\n\nСкидка: '+money(t.discount)+'\nДоставка: '+money(t.delivery)+'\nИтого: '+money(t.grand)+'\n\nРеальный заказ не оформлен. Контактные данные не включены.';$('#order-dialog-summary').textContent='Товаров: '+state.items.reduce((n,x)=>n+x.qty,0)+'. Итого: '+money(t.grand)+'.';$('#order-result').textContent='Учебный заказ проверен. Данные не передавались.';const dialog=$('#order-dialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');});$('#order-dialog .dialog-close').addEventListener('click',()=>{const d=$('#order-dialog');if(typeof d.close==='function')d.close();else d.removeAttribute('open');});$('#download-order').addEventListener('click',()=>{if(!receipt)return;const url=URL.createObjectURL(new Blob(['\uFEFF'+receipt],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='lapki-demo-order.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
$('#clear-local-data')?.addEventListener('click',()=>{state={items:[],coupon:'',delivery:'pickup'};try{localStorage.removeItem(KEY);}catch{}refresh();$('#clear-result').textContent='Корзина и настройки очищены.';});
window.addEventListener('storage',e=>{if(e.key===KEY)location.reload();});
refresh();
})();
